//! Differential test: every fixture's `alien.toml` must resolve to the stack its `alien.ts`
//! produces with the TypeScript SDK.
//!
//! `expected.json` is the TypeScript output, regenerated by `tests/fixtures/regenerate.sh`.
//! Both sides go through `alien_core::Stack`, exactly as `alien build` loads an alien.ts,
//! so the comparison is between the stacks a release would carry.

use std::path::{Path, PathBuf};

use alien_core::Stack;

/// Every fixture directory, or only those named in `FIXTURE` (a space separated list) while
/// working on one.
fn fixtures() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures");
    let only: Option<Vec<String>> = std::env::var("FIXTURE")
        .ok()
        .map(|names| names.split_whitespace().map(str::to_string).collect());
    let mut fixtures: Vec<PathBuf> = std::fs::read_dir(&root)
        .expect("fixtures directory is readable")
        .map(|entry| entry.expect("fixture entry is readable").path())
        .filter(|path| path.is_dir())
        .filter(|path| {
            only.as_ref().is_none_or(|names| {
                names
                    .iter()
                    .any(|name| path.file_name().is_some_and(|file| file == name.as_str()))
            })
        })
        .collect();
    fixtures.sort();
    fixtures
}

fn typescript_stack(fixture: &Path) -> Stack {
    let json = std::fs::read_to_string(fixture.join("expected.json"))
        .expect("expected.json exists; run tests/fixtures/regenerate.sh");
    serde_json::from_str(&json).expect("the TypeScript SDK output is a valid Stack")
}

#[test]
fn toml_stacks_match_their_typescript_equivalents() {
    let fixtures = fixtures();
    assert!(!fixtures.is_empty(), "no fixture matched");

    for fixture in fixtures {
        let toml_stack = alien_stack_toml::load(&fixture.join("alien.toml"))
            .unwrap_or_else(|error| panic!("{}: {error}", fixture.display()));
        let ts_stack = typescript_stack(&fixture);

        let toml_json = serde_json::to_value(&toml_stack).unwrap();
        let ts_json = serde_json::to_value(&ts_stack).unwrap();
        let mut differences = Vec::new();
        diff("", &toml_json, &ts_json, &mut differences);
        assert!(
            differences.is_empty(),
            "{}: alien.toml and alien.ts resolve to different stacks:\n{}",
            fixture.display(),
            differences.join("\n"),
        );
        // Order matters where the stack keeps lists (inputs, endpoints, capacity groups).
        assert_eq!(toml_stack, ts_stack, "{}", fixture.display());
    }
}

/// Paths where two JSON values differ, with both sides.
fn diff(path: &str, toml: &serde_json::Value, ts: &serde_json::Value, out: &mut Vec<String>) {
    use serde_json::Value;
    match (toml, ts) {
        (Value::Object(left), Value::Object(right)) => {
            let mut keys: Vec<&String> = left.keys().chain(right.keys()).collect();
            keys.sort();
            keys.dedup();
            for key in keys {
                let null = Value::Null;
                diff(
                    &format!("{path}.{key}"),
                    left.get(key).unwrap_or(&null),
                    right.get(key).unwrap_or(&null),
                    out,
                );
            }
        }
        (Value::Array(left), Value::Array(right)) if left.len() == right.len() => {
            for (index, (left, right)) in left.iter().zip(right).enumerate() {
                diff(&format!("{path}[{index}]"), left, right, out);
            }
        }
        (left, right) if left != right => {
            out.push(format!("  {path}: alien.toml {left} != alien.ts {right}"))
        }
        _ => {}
    }
}
